  function describeTerminalRest(lesson,adapter){
    const bpm=56,beatMs=60000/bpm;
    lesson.timeLimit=24;
    lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-terminal-rest-v1',bpm,practiceBpm:bpm,timeSignature:{numerator:4,denominator:4},steps:[0,2].map((start,i)=>({startBeat:start,durationBeats:1,restBeforeBeats:i?1:0,measure:1,beatInMeasure:start,sourceStartMs:Math.round(start*beatMs),sourceDurationMs:Math.round(beatMs)}))},2);
    lesson.guide=adapter.normalizeGuide({stage:'Ритм: конечная четвертная пауза',setup:'Сначала повтори «Пауза — тоже доля» и «Правая: окончание одного звука». Найди среднее до C4 слева от пары чёрных клавиш, большой палец правой 1 над ним. Без педали; остальные клавиши свободны.',motion:'Считай «раз, два, три, четыре, раз». На первое «раз» нажми C4; на «два» отпусти. На «три» повторно нажми C4; на «четыре» отпусти. Последнее «раз» только отмечает конец: не играй новую ноту.',blind:'Представь «до — тишина — до — тишина» в ровном пульсе. После разбора попробуй режим памяти: ни готовый экран, ни следующее нажатие не заменяют внутренний счёт.',mastery:'Две атаки и два отпускания, обе паузы слышны, последняя доля не сокращена. MIDI ждёт границы после четырёх долей и проверяет запись событий; пальцы, расслабление и акустическую тишину оцени сам или с педагогом.'});
    Object.assign(lesson.learning,{coverageDomain:'rhythm',articulation:'nonlegato',timingPrecision:'beat-boundary-v1',ending:{version:1,endBeat:4},nextLessonId:'detail-p-rhythm-04',goal:terminalRest.goal,
      practiceSteps:[
        'Подготовка: правая уже находит и освобождает C4 большим пальцем 1. В прежнем уроке внутреннюю паузу ограничивала следующая нота; теперь после последнего отпускания новой атаки нет. Прочитай четверть — четвертная пауза — четверть — четвертная пауза в одном такте 4/4.',
        'Медленно считай четыре равные доли: «раз» — C4, «два» — отпустить и тишина, «три» — C4, «четыре» — отпустить и тишина. Слово «четыре» начинает последнюю долю, а не заканчивает фразу. Дойди до следующего «раз» без третьего нажатия; затем остановись.',
        'Послушай образец целиком, включая конечную тишину. Представь два одинаковых до с двумя равными промежутками тишины; простучи пульс отдельно от клавиш. Не сокращай вторую паузу из-за отсутствия следующей ноты. Знакомый образец служит слуховому представлению, а не независимому тесту слуха.',
        'Блок около 3–5 минут: короткий разбор, несколько спокойных попыток с отдыхом и самопроверка; при напряжении остановись. После попытки вне MIDI-зачёта попробуй новую фразу: три C4 на «раз, два, три», затем полная доля тишины на «четыре» до следующего «раз». Каждому повтору нужна новая атака. Вернись к исходной фразе после перерыва, затем отдельно из памяти на следующий день. Это перенос в новый рисунок, не дополнительный урок.'
      ],
      selfCheck:['Правая C4, большой палец 1; два нажатия не заменены одним удержанием. MIDI палец не видит.','Обе ноты длятся по одной доле; вторая отпущена у начала «четыре», а не держится до конца такта.','После последнего отпускания сохрани полную долю до следующего «раз», без новой ноты и без педали.','Не жди экранной подсказки в памяти: внутренний счёт продолжается до конца. Следующее «раз» отмечает границу, не новую атаку.','Перенос в три C4 и конечную паузу выполняется отдельно; удобство, слуховой образ и устойчивость после перерыва требуют собственной проверки.'],
      rhythmNotice:'Техническое упражнение проекта. Конечная пауза имеет явную границу после четырёх долей. Темп 56 BPM и небольшие MIDI-допуски — настройки проекта, не нормы авторов источников.',
      references:[REST_VALUES,'https://viva.pressbooks.pub/openmusictheorycopy/chapter/simple-meter-and-time-signatures/'],
      referenceTitles:{[REST_VALUES]:'Open University / OpenLearn: 4.1 Values and dots, Example 32',['https://viva.pressbooks.pub/openmusictheorycopy/chapter/simple-meter-and-time-signatures/']:'Hamm, Shaffer, Gotham: Simple Meter, Counting, Examples 10–13'},
      sourceEvidenceIds:['ou-rest-values-2026-11-05','omt-simple-counting-2026-11-05'],
      provenance:{type:'project-technical-drill',author:'Упражнение проекта',purpose:'Сохранить внутренний пульс на конечной паузе, когда нет следующей атаки, которая показала бы её конец.',context:'Так заканчиваются короткие фразы и ответы перед следующим вступлением. Навык полезен при чтении, игре с партнёром и самостоятельном сопровождении.',sourceNote:'Последовательность C4 и её аппликатура созданы проектом. OpenLearn подтверждает длительности тишины, Open Music Theory — счёт и размер 4/4; это не цитата из произведения и не упражнение, утверждённое авторами. У издания copy и исходного URL различается нумерация примеров; здесь прочитаны Time Signatures / Counting, Examples 10–13.'}
    });
  }
  function rhythmFromDurations(durations,bpm,source,adapter){
    let cursor=0;
    return adapter.normalizeRhythm({version:1,source,bpm,practiceBpm:bpm,timeSignature:{numerator:4,denominator:4},steps:durations.map(duration=>{const start=cursor;cursor+=duration;return {startBeat:start,durationBeats:duration,restBeforeBeats:0,measure:Math.floor(start/4)+1,beatInMeasure:start%4,sourceStartMs:Math.round(start*60000/bpm),sourceDurationMs:Math.round(duration*60000/bpm)};})},durations.length);
  }
  function describePositionReturn(lesson,adapter){
    const l=lesson.learning,starts=[0,2,3,4,6],durations=[1,1,1,1,2];
    lesson.timeLimit=24;lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-position-return-v1',bpm:48,practiceBpm:48,timeSignature:{numerator:2,denominator:4},steps:starts.map((start,i)=>({startBeat:start,durationBeats:durations[i],restBeforeBeats:i===1||i===4?1:0,measure:Math.floor(start/2)+1,beatInMeasure:start%2,sourceStartMs:start*1250,sourceDurationMs:durations[i]*1250}))},5);
    lesson.guide=adapter.normalizeGuide({...lesson.guide,stage:'Смена двух подготовленных позиций',setup:'Правая начинает в C4–G4, большой 1 у C4. Затем вся рука смещается в D4–A4: большой над D4, 4 над G4, 5 над A4. Ничего не удерживай ради охвата C–A; левая отдыхает, педаль выключена.',motion:'Отпусти C4 и в однодольной паузе перенеси всю руку к D4–A4. Сыграй G4–A4–G4 пальцами 4–5–4. После последнего G4 снова отпусти клавишу, в паузе вернись к C4–G4 и сыграй F4 тем же пальцем 4 новым нажатием.',blind:'Сначала найди обе позиции глазами. После разбора попробуй вспомнить их; если ориентир потерян, остановись и проверь клавиши, не разыскивай их на ходу нажатиями.',mastery:'Проверь две внутренние паузы и две полные доли F4. Отдельно наблюдай перенос всей руки и её свободу: MIDI не определяет пальцы и положение ладони. Вернись после перерыва и примени движение в новой короткой фразе.'});
    l.coverageDomain='positions';l.timingPrecision='beat-boundary-v1';l.nextLessonId='course09-03';
    l.positionCues=[{stepIndex:1,text:'В паузе отпусти C4 и перенеси всю правую руку в D4–A4: G4 играет 4, A4 — 5.'},{stepIndex:4,text:'В паузе отпусти G4 и верни всю правую руку в C4–G4. Теперь F4 играет 4 новым нажатием.'}];
    l.practiceSteps=[
      'Подготовка: повтори перенос большим пальцем, пару 4–5 и половинную ноту. Найди C4–G4, затем без звука D4–A4; пальцы только касаются своих ориентиров, не нажимая все клавиши. Послушай C4 — тишина — G4–A4–G4 — тишина — F4. Это смена позиции, а не неподвижный охват шести белых клавиш.',
      'Медленный разбор: четыре такта 2/4, счёт «раз, два». Такт 1: C4 большим 1 на «раз», отпусти на «два» и перенеси руку в D4–A4. Такт 2: G4/4 на «раз», A4/5 на «два». Такт 3: G4/4 на «раз», отпусти на «два» и вернись к C4–G4. Такт 4: F4/4 держи через «раз, два» до следующего мысленного «раз». Между G4 и F4 тот же палец отпускается и получает новое нажатие; это не подмена на удержанной ноте.',
      'Блок около 3–5 минут: сначала каждый перенос в тишине, затем все пять звуков в удобном медленном пульсе и при 48 BPM. Не добавляй долю в паузы. После попытки сыграй C4/1 — пауза — A4/5–G4/4–A4/5 — пауза — F4/4 с теми же позициями и ритмом. Это отдельная проба переноса, не текущий MIDI-зачёт и не новый урок. Вернись после перерыва. Дальше можно применить движение в Twinkle с более короткими отпусканиями; конкретная мелодия не обязательна для общего навыка смены позиции.'
    ];
    l.selfCheck=['Не удерживай C4 и не тяни мизинец к A4 из неподвижной ладони. После отпускания передвигается вся рука; запястье остаётся свободным.','Не оставляй руку в D4–A4 для последней F4: тогда F оказывается под другим пальцем. В паузе верни позицию C4–G4, а затем заново нажми F4 пальцем 4.','Слышны две однодольные паузы и длинный последний F4. Не сокращай последний звук до одной доли; конец — через восемь долей.','Пальцы, комфорт, внутренний счёт и музыкальное качество проверь отдельно. MIDI измеряет только высоты, вступления и отпускания в допусках проекта; знакомый образец не является независимой слуховой пробой.'];
    l.rhythmNotice='Пять звуков в четырёх тактах 2/4: начала на долях 0, 2, 3, 4, 6; длительности 1, 1, 1, 1, 2. Две внутренние паузы по одной доле, конечной паузы нет; последнее отпускание — через 8 долей. 48 BPM и допуски — настройки проекта.';
    l.references=[POSITION_CONTEXT,TIME_VALUES,PRACTICE,TECHNIQUE];l.referenceTitles={[POSITION_CONTEXT]:'Jerry Kovarsky: планировать смену положения руки',[TIME_VALUES]:'The Open University: четверти и половинные',[PRACTICE]:'Bob Duke и Amy Simmons: короткая цель и перенос',[TECHNIQUE]:'Diana Dumlavwalla: свободное запястье'};l.sourceEvidenceIds=['kovarsky-fingering-context-2026-11-05','ou-time-values-2026-11-05','duke-simmons-small-goals-2026-11-05','dumlavwalla-basic-technique-2026-11-05'];
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:'Подготовить перенос C4/1 → G4/4 в позицию D4–A4 и обратное перемещение G4/4 → F4/4 после отпускания. Затем применить два положения в короткой мелодии.',context:'Пять пальцев могут обслуживать больший диапазон последовательно, меняя положение руки. Это отличается от переноса 1→1 к новому большому пальцу и от пары 4–5 в неподвижной позиции.',sourceNote:'Собственная техническая последовательность проекта, не упражнение Моцарта. Kovarsky, вводный абзац и Scenario Three, предлагает заранее планировать пальцы и смены положения, когда фраза не помещается в одной позиции. Ноты, два положения, пальцы 1–4–5–4–4, паузы, 48 BPM и проверочные допуски выбраны проектом. Источник не утверждает этот урок и не подтверждает удобство для каждой руки.'};
  }
  function describeDottedQuarter(lesson,adapter){
    const l=lesson.learning;lesson.rhythm=rhythmFromDurations([1.5,.5,2,1.5,.5,2],48,'project-dotted-quarter-v1',adapter);lesson.timeLimit=30;
    lesson.guide=adapter.normalizeGuide({stage:'Точка: полторы доли без спешки',setup:'Правая в позиции C4–G4: средний 3 у E4, указательный 2 у D4. Левая отдыхает, педаль выключена. Сначала повтори половинную и пары восьмых.',motion:'Держи E4 через три равные восьмые, затем передай звук D4. Перед второй D4 освободи клавишу и нажми тем же указательным 2 заново; удерживай две доли без лишнего давления.',blind:'Сначала услышь и простучи длинный–короткий–длинный рисунок. После разбора вспомни E4 и D4 в подготовленной позиции; не ищи клавиши силой или высоким замахом.',mastery:'Сохрани «раз-и, два-и» во время долгой E4, затем короткую D4 и новое нажатие D4 на «три». MIDI не определяет пальцы и свободу руки. Повтори после перерыва и перенеси рисунок на другую знакомую пару.'});
    l.coverageDomain='rhythm';l.timingPrecision='beat-boundary-v1';l.nextLessonId='course04-08';
    l.practiceSteps=['Подготовка: поставь правые 3–2 у E4–D4. Произнеси восемь равных половинок: «раз-и, два-и, три-и, четыре-и». Точка добавляет к четверти ещё восьмую: полторы доли равны трём восьмым. Послушай образец и заранее услышь длинный E4, короткий D4 и новый длинный D4.',
      'Медленный разбор: нажми E4 на «раз» и держи через «раз-и, два». На «два-и» отпусти E4 и сыграй D4 на полдоли. На «три» отпусти и заново нажми D4 тем же пальцем 2, держи через «четыре-и» до следующего «раз». Повтори такт. Вступления 0 / 1,5 / 2 / 4 / 5,5 / 6, конец через 8 долей. Пауз в нотном рисунке нет; два D4 не склеиваются в один удержанный звук.',
      'Блок около 3–5 минут: счёт и простукивание, один такт в удобном медленном пульсе, затем два такта при 48 BPM. После попытки сыграй E4–F4–F4 правыми 3–4–4 с теми же длительностями. Это самостоятельная проба переноса, не текущий MIDI-зачёт. Вернись после перерыва. Можно применить рисунок в подготовленной музыкальной фразе; прохождение конкретной пьесы для дальнейшего изучения ритма не требуется.'];
    l.selfCheck=['Не превращай полторы доли и полдоли в две одинаковые четверти.','Не начинай короткую D4 на «два»: её место — «два-и».','Вторая D4 получает новое нажатие на «три», а не продолжение прежнего удержания.','Слышны три восьмых длительности первого звука, одна восьмая второго и четыре восьмых последнего; пульс одинаков.','MIDI проверяет высоты, атаки и отпускания в допусках проекта, но не пальцы, комфорт или художественное качество. Известный образец не является независимым тестом слуха.'];
    l.rhythmNotice='Два полных такта 4/4, без внутренних пауз и конечной паузы в данных. Четверть с точкой = 1,5 доли, восьмая = 0,5, половинная = 2. Последнее отпускание через 8 долей обязательно. 48 BPM и допуски выбраны проектом.';
    l.references=[DOTS,TIME_VALUES,PRACTICE];l.referenceTitles={[DOTS]:'The Open University: точка и три восьмых',[TIME_VALUES]:'The Open University: отношения длительностей',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель практики'};l.sourceEvidenceIds=['ou-dots-and-ties-2026-11-05','ou-time-values-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:'Удержать полторы доли без ускорения, вступить на вторую половину доли и заново нажать повторённую ноту на сильную долю.',context:'Пунктирный рисунок пригодится в мелодиях и ритмических вариациях; затем его можно применить в учебной адаптации «Оды к радости».',sourceNote:'Самостоятельная ритмическая подготовка проекта. OpenLearn, §3.5, Example 18 объясняет точку как прибавление половины длительности и равенство четверти с точкой трём восьмым. Ноты E4/D4, пальцы, два повтора, перенос, 48 BPM и допуски выбраны проектом; источник не утверждает этот урок.'};
  }
  function describeLeftDuration(lesson,spec,adapter){
    const l=lesson.learning,whole=spec.duration===4,bpm=56;
    lesson.timeLimit=24;lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-left-duration-v1',bpm,practiceBpm:bpm,timeSignature:{numerator:4,denominator:4},steps:Array.from({length:spec.count},(_,i)=>({startBeat:i*spec.duration,durationBeats:spec.duration,restBeforeBeats:0,measure:Math.floor(i*spec.duration/4)+1,beatInMeasure:i*spec.duration%4,sourceStartMs:Math.round(i*spec.duration*60000/bpm),sourceDurationMs:Math.round(spec.duration*60000/bpm)}))},lesson.steps.length);
    lesson.guide=adapter.normalizeGuide({stage:'Левая рука: '+(whole?'четыре доли':'две доли'),setup:'Найди C3 слева от пары чёрных клавиш ниже среднего до. Левый мизинец 5 у C3, остальные пальцы спокойно рядом; правая отдыхает. Без педали. Не фиксируй кисть и не добавляй давления во время удержания.',motion:whole?'На «раз» нажми C3 мизинцем, продолжай «два, три, четыре». Слово «четыре» только начинает последнюю долю: отпусти и заново нажми у следующего «раз». Последний звук тоже заверши у границы следующего такта.':'Нажми C3 на «раз», держи через «два»; у «три» освободи клавишу и нажми её заново. Держи через «четыре», следующий повтор — на новом «раз». После атаки сохрани свободную руку, без высокого замаха.',blind:'Сначала найди C3 глазами и по чёрным клавишам, послушай образец. После разбора попробуй отдельный MIDI-режим памяти; при потере позиции остановись и проверь руку.',mastery:'Слышны отдельные ровные длинные звуки; повтор высоты нельзя заменить одним общим удержанием. MIDI проверяет ноты и границы, не мизинец и свободу руки. Вернись после перерыва и попробуй соседнюю опору.'});
    l.coverageDomain='rhythm';l.articulation='standard';l.timingPrecision='beat-boundary-v1';l.goal=spec.goal;l.nextLessonId=whole?'course04-04':'detail-p-left-whole-01';
    l.practiceSteps=[
      'Подготовка: '+(whole?'сначала удержи C3 левой на две доли в «Левая: половинные мизинцем».':'сначала найди C3 левым мизинцем в «Левая: найди C3 / До». Здесь сохраняется та же клавиша и тот же палец; удлиняется удержание.')+' Назови ноту и палец, послушай два такта образца. Левая самостоятельно удерживает и освобождает клавишу; правая не помогает. Темп тот же, что у соответствующего правого упражнения: новая задача связана с левой рукой и мизинцем, не с BPM.',
      'Медленный разбор: '+(whole?'считай «раз, два, три, четыре». Одно нажатие длится весь такт. Не снимай палец на начале «четыре», дойди до следующего «раз»; на этой границе отпусти и повторно нажми C3. Два звука заканчиваются через восемь долей.':'считай «раз, два, три, четыре». Первое C3 занимает «раз–два», второе — «три–четыре»; повтори так же во втором такте. Четыре отдельных нажатия заканчиваются через восемь долей.')+' Между нажатиями счётных пауз нет: клавиша освобождается для новой атаки у границы. Сначала одна длительность в удобном медленном пульсе, затем два такта при учебных 56 BPM.',
      'Блок около 3–5 минут: короткий разбор, исходная фраза и остановка для проверки. Не дави сильнее ради удержания, при напряжении остановись. После завершения попытки заранее найди D3 без звука и отдельно сыграй '+(whole?'один D3 на четыре доли':'два D3 по две доли')+' тем же левым мизинцем 5; не растягивай удержанную руку до соседней клавиши. Это самостоятельная проба переноса на новую опору, не текущий MIDI-зачёт и не дополнительный урок. После перерыва вернись к C3. Следующий шаг — '+(whole?'соединить знакомые четверти и половинную без изменения пульса.':'удержать левой один звук целый такт в следующем уроке.')
    ];
    l.selfCheck=['Левая играет C3 мизинцем 5, правая отдыхает. Удобство и палец проверяются самостоятельно или с педагогом, MIDI их не видит.',whole?'Удерживай все четыре доли до нового «раз», а не только до начала слова «четыре».':'Одна атака занимает две доли, не две отдельные четверти.',whole?'Два целых звука требуют двух нажатий, не одного удержания на восемь долей.':'Четыре половинных требуют четырёх нажатий; не сливай их в один звук.', 'Счёт продолжается внутри удержания. Нет лишней тишины или силового давления; при напряжении вернись к короткому разбору.','Известный образец помогает представить звучание, но не является независимым слуховым тестом. Повтор после перерыва и новая опора проверяются отдельно.'];
    l.rhythmNotice='Два такта 4/4: '+(whole?'два целых C3 по четыре доли':'четыре половинных C3 по две доли')+', всего восемь долей, 56 BPM, без счётных пауз. Последнее отпускание проверяется, конечная тишина после него не измеряется. Ограниченный допуск удержания принадлежит проекту.';
    l.references=[TIME_VALUES,SIMPLE_COUNTING,TECHNIQUE,PRACTICE];l.referenceTitles={[TIME_VALUES]:'The Open University: половинная и целая',[SIMPLE_COUNTING]:'Gotham, Hamm, Shaffer: четыре доли и продолжение счёта',[TECHNIQUE]:'Diana Dumlavwalla: свободная рука и запястье',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель и возвращение'};l.sourceEvidenceIds=['ou-time-values-2026-11-05','omt-simple-counting-2026-11-05','dumlavwalla-basic-technique-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:whole?'Освоить полное четырёхдольное удержание и повторную атаку левым мизинцем после двухдольной подготовки.':'Подготовить самостоятельное двухдольное удержание и повторную атаку левым мизинцем в раннем курсе, без третьей доли паузы.',context:'Длинные ноты левой руки используются в басе и сопровождении. Это одно последовательное голосовое движение без удержанного баса под другой партией. Поздний левый пульс 3/4 уже содержит две доли звучания, но не заменяет раннюю подготовку без пауз и последующее четырёхдольное удержание.',sourceNote:'Собственная техническая последовательность проекта, не фрагмент произведения и не упражнение, рекомендованное авторами именно в этом виде. OpenLearn, §3.1, Examples 13–14, подтверждает отношения длительностей; Open Music Theory, Counting in Simple Meter, Example 10 и правила долгих звуков, — продолжение счёта. Dumlavwalla, разделы о напряжении руки и форме кисти, поддерживает свободное движение; её упражнения с поддержкой и отпусканием руки здесь не назначаются. C3/D3, палец 5, порядок, 56 BPM, размер блока и машинные допуски заданы проектом. Исторических атрибуций нет.'};
  }
  function describeLeftTriplePulse(lesson,adapter){
    const l=lesson.learning;
    lesson.timeLimit=24;lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-left-triple-pulse-v1',bpm:48,practiceBpm:48,timeSignature:{numerator:3,denominator:4},steps:[0,3,6].map((start,i)=>({startBeat:start,durationBeats:2,restBeforeBeats:i?1:0,measure:i+1,beatInMeasure:0,sourceStartMs:start*1250,sourceDurationMs:2500}))},3);
    lesson.guide=adapter.normalizeGuide({...lesson.guide,stage:'Левая: звук и тишина в 3/4',setup:'Найди C3 левой рукой, поставь мизинец 5 у поверхности клавиши. Педаль выключена, кисть свободна.',motion:'Удерживай клавишу через «раз, два». На «три» освободи её и оставайся рядом, готовя новое нажатие на следующем «раз».',blind:'Сначала спокойно найди C3 по группе чёрных клавиш. После разбора попробуй вспомнить опору; при потере ориентира остановись и проверь клавиатуру.',mastery:'Проверь удержание двух долей и две внутренние паузы. Последнее отпускание обязательно; последующая тишина измерением не подтверждается. Пальцы и свободу руки проверь отдельно, затем повтори после перерыва.'});
    l.coverageDomain='rhythm';l.timingPrecision='beat-boundary-v1';l.nextLessonId='detail-p-minor-triads-04';
    l.practiceSteps=['Подготовка: повтори мини-фразу левой руки и окончание одного звука. Найди C3 мизинцем 5, проговори три ровных счёта без игры. Услышь длинный C3, короткую тишину и новое вступление.','Медленный разбор: на «раз» нажми C3, через «два» продолжай удерживать, на «три» полностью отпусти. До следующего «раз» не добавляй звук. Так начинаются три группы на долях 0, 3 и 6; каждая нота длится две доли. Последний C3 отпускается на «три» третьего такта, через восемь долей; автоматическая попытка заканчивается здесь.','Блок около 3–5 минут: сначала одна группа в удобном медленном пульсе, затем три при 48 BPM. Досчитай последнюю тишину самостоятельно. После попытки попробуй тот же счёт на E3 средним 3 левой руки; это отдельная проба переноса, не фраза текущего MIDI-зачёта. После перерыва вернись к C3. Следующий шаг — удержать две доли левое созвучие и подготовить смену в тишине.'];
    l.selfCheck=['Каждые три счёта занимают одинаковое время: не сокращай «три» перед новым нажатием.','Слышны два отдельных промежутка тишины. Не продолжай держать C3 в паузе и не начинай следующую ноту раньше «раз».','Мизинец остаётся близко к клавише, кисть свободна. MIDI не доказывает палец, комфорт, акценты и художественное качество.','Известный образец помогает представить звук, но не является независимым тестом слуха. Отложенный повтор и перенос оцениваются отдельно.'];
    l.rhythmNotice='Три вступления C3 левой рукой в размере 3/4: начала 0/3/6, длительности по две доли, две внутренние паузы по одной. Последнее отпускание на 8-й доле завершает наблюдение; конечная пауза не оценивается. 48 BPM и числовые допуски выбраны проектом. Штрих standard не требует отдельного legato/staccato.';
    l.references=[TIME_VALUES,METER,PRACTICE,CZERNY];l.referenceTitles={[TIME_VALUES]:'The Open University: отношения длительностей',[METER]:'Robert Hutchinson: три доли в такте',[PRACTICE]:'Bob Duke и Amy Simmons: короткая цель и перенос',[CZERNY]:'Carl Czerny: удержание и паузы, письмо 3'};l.sourceEvidenceIds=['ou-time-values-2026-11-05','hutchinson-meter-2026-11-05','duke-simmons-small-goals-2026-11-05','czerny-letter3-release-2026-11-05'];
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:'Удержать левой рукой звук на две доли и сохранить третью долю тишины в трёхдольном пульсе.',context:'Подготовка левой руки к смене аккордов в тишине; трёхдольный пульс пригодится в простом вальсовом сопровождении, которое вводится отдельно.',sourceNote:'Собственная техническая задача, не фрагмент произведения. OpenLearn подтверждает отношения длительностей, Hutchinson — три доли в трёхдольном размере, Черни в письме 3 различает удержание ноты и паузу. Конкретные C3, палец 5, рисунок и 48 BPM выбраны проектом; авторы источников их не утверждали.'};
  }
  function describeLeftPositionStudy(lesson,spec,adapter){
    const bpm=48,l=lesson.learning;
    lesson.rhythm=adapter.normalizeRhythm({version:1,source:'project-left-position-v1',bpm,practiceBpm:bpm,timeSignature:{numerator:4,denominator:4},steps:spec.starts.map((start,i)=>({startBeat:start,durationBeats:spec.durations[i],restBeforeBeats:i?Math.max(0,start-spec.starts[i-1]-spec.durations[i-1]):0,measure:Math.floor(start/4)+1,beatInMeasure:start%4,sourceStartMs:Math.round(start*60000/bpm),sourceDurationMs:Math.round(spec.durations[i]*60000/bpm)}))},spec.events.length);
    lesson.timeLimit=Math.ceil((spec.starts.at(-1)+spec.durations.at(-1))*60/bpm*1.8+10);
    lesson.guide=adapter.normalizeGuide({stage:spec.groupTitle,setup:'Сядь устойчиво, стопы на опоре, предплечье примерно на уровне клавиш. Педаль не используется. '+spec.position,motion:spec.breakdown,blind:'Сначала послушай образец и заранее представь ноты. После разбора исходной фразы повтори без подсказок; новую позицию не ищи вслепую до её освоения.',mastery:'Три чистые MIDI-попытки, одна из памяти; повтор после перерыва, например завтра. Пальцы и свободу руки проверь самостоятельно или с педагогом. '+spec.next});
    l.coverageDomain=spec.coverageDomain;l.timingPrecision=spec.precision;
    l.practiceSteps=['Подготовка: '+spec.position+' Послушай образец и назови звуки в удобной голосу октаве.','Медленный разбор: '+spec.breakdown+' '+spec.count,'Короткий блок около 3–5 минут: отдельные опоры, исходная фраза и остановка для проверки. '+spec.transfer+' Это самостоятельная проба, а не автоматический независимый тест слуха.'];
    l.selfCheck=[...spec.errors,spec.hearing,'MIDI проверяет высоты, вступления и отпускания. Он не видит пальцы и физическое удобство; известная фраза не является независимым тестом слуха.',spec.next];
    l.limitations=['Аппликатура 5–3–1 выбрана проектом для этого регистра; её удобство зависит от руки и требует самостоятельной или педагогической проверки.','Удержанные голоса и педаль в этих заданиях не используются. Последнее отпускание завершает фразу; конечная пауза не оценивается.'];
    l.rhythmNotice='Техническое упражнение проекта: 4/4, 48 BPM, '+(spec.coverageDomain==='positions'?'два такта с указанными четвертями и половинными; legato проверяется только между последовательными одиночными звуками.':'один такт из четырёх четвертей; последний аккорд требует нового общего нажатия и окончания. Специальный профиль legato/staccato не назначается.')+' Темп и числовые допуски выбраны проектом.';
    l.references=[THEORY,POSITION_CONTEXT,TECHNIQUE,PRACTICE];l.referenceTitles={[THEORY]:'The Open University: §7, строение трезвучия',[POSITION_CONTEXT]:'Jerry Kovarsky: заранее выбрать позицию и пальцы',[TECHNIQUE]:'Diana Dumlavwalla: свободное запястье и посадка',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель практики'};
    l.sourceEvidenceIds=['ou-triads-2026-11-05','kovarsky-fingering-context-2026-11-05','dumlavwalla-basic-technique-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:spec.purpose,context:spec.context,sourceNote:'Ноты, регистр, пальцы, ритм и порядок задания созданы проектом. OpenLearn, §7 и Example 63, подтверждает состав и интервалы трезвучий; Kovarsky, The Basics и Scenario One, — нумерацию и предварительную подготовку позиции. Dumlavwalla, Inconsistent Hand Shape, — гибкость запястья. Эти источники не назначают наши конкретные левые 5–3–1, не утверждают урок и не подтверждают обучение знаменитого исполнителя по нему.'};
  }
