  function reviewDyads(lessons,adapter){
    let changed=0;
    for(const r of dyadReviews){
      const lesson=lessons.find(l=>l.id===r.id),l=lesson?.learning;
      if(!l||lesson.contentKind!=='exercise'||l.contentReview||instructionFingerprint(lesson)!==r.fingerprint)continue;
      const previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson),hand=r.hand==='right'?'правой':'левой';
      lesson.description='Четыре раза сыграй '+r.notes+' '+hand+' рукой '+r.digits+'. Подготовь два касания, начни оба звука вместе и освободи обе клавиши у общего окончания. Это '+r.quality+'.';
      lesson.guide=adapter.normalizeGuide({stage:'Две ноты одной рукой: подготовить и отпустить вместе',setup:'Сначала повтори пятипальцевую позицию и окончание звука своей руки. '+r.position+'. '+(r.hand==='left'?'C3 находится на октаву ниже среднего C4. ':'C4 — среднее до. ')+'Вторая рука отдыхает, педаль выключена. Не фиксируй запястье и не прижимай лишние клавиши.',motion:r.motion,blind:'Услышь один совместный вход двух высот, затем их общее отпускание и короткий просвет. Заранее найди обе клавиши глазами; после уверенного разбора представь известный образец и попробуй память. Это не независимый тест слуха.',mastery:'Четыре совместных вступления и четыре общих отпускания без пропуска одного тона. MIDI проверяет записанные ноты и границы в пределах допусков проекта; номера пальцев, свободу руки и звучание проверь отдельно у инструмента.'});
      l.stage='p2';l.goal=lesson.description;l.requires=[...r.requires];l.coverageDomain='intervals';l.timingPrecision='beat-boundary-v2';l.nextLessonId=r.next;
      l.practiceSteps=[
        'Подготовка: '+r.position+'. Сначала назови ноты и пальцы, коснись обеих клавиш без звука, проверь каждую по отдельности; затем возьми только один двузвук. '+r.motion+' Между нотами по названиям — одна пропущенная белая клавиша. '+r.notes+' — '+r.quality+'. Это две одновременные высоты, а не последовательная мелодия.',
        'Медленно разбери один совместный вход и одно отпускание, остановись и проверь руку. Затем четыре вступления на «раз, два, три, четыре» при 56 BPM. Звучание каждой пары — 0,85 доли (около 911 мс), просвет до следующего вступления — 0,15 (около 161 мс). Освобождай обе клавиши немного до следующего счёта; не удерживай их как полные четверти и не заменяй повтор одним общим удержанием. Последнее окончание — через 3,85 доли от начала; конечная тишина здесь отдельно не оценивается.',
        'Блок около 3–5 минут: несколько спокойных проб с остановками и отдыхом, без наращивания давления. После исходной четвёрки отдельно сыграй новую фразу: ту же пару '+r.notes+' пальцами '+r.digits+' на «раз» и «три», с тем же коротким общим окончанием; на «два» новой атаки нет. После второй пары освободи клавиши и остановись. Это другая фраза с промежутком, не текущий MIDI-зачёт и не новый урок. Вернись к исходной четвёрке после перерыва и отдельно из памяти на следующий день. '+r.nextText
      ];
      l.selfCheck=['Используется '+(r.hand==='right'?'правая':'левая')+' рука '+r.digits+' на '+r.notes+'; соседняя белая между ними не нажата. MIDI не определяет пальцы.','Слышны обе высоты с одним входом, без ступенчатого перебора. Если один тон постоянно опаздывает, вернись к одному подготовленному двузвуку.','Обе клавиши заканчиваются вместе; один ранний или оставшийся тон меняет окончание. При повторе обеим нотам нужна новая атака.','Кисть подвижна, свободные пальцы не зажаты. Не добивайся одинаковой формы пальцев силой; при напряжении остановись и проверь положение с педагогом.','Известный образец помогает представить созвучие, но не доказывает независимое распознавание на слух. Пробу с новым ритмическим рисунком выполняй отдельно.',r.nextText];
      l.rhythmNotice='Техническое упражнение проекта: четыре одинаковых двузвука, 56 BPM, звучание 0,85 доли и просвет 0,15 перед следующим вступлением. Высоты, пальцы и исходный ритм сохранены. Проверка общего отпускания обновлена на beat-boundary-v2; для этой редакции нужен новый повтор, прежняя история сохраняется. Числовые MIDI-допуски заданы проектом.';
      l.references=[INTERVALS,POSITION_CONTEXT,TECHNIQUE,CZERNY,PRACTICE];l.referenceTitles={[INTERVALS]:'Open University: §6.4, гармонический и мелодический интервал',[POSITION_CONTEXT]:'Jerry Kovarsky: номера пальцев и подготовленная позиция',[TECHNIQUE]:'Diana Dumlavwalla: поддержанная рука и гибкое запястье',[CZERNY]:'Карл Черни: письмо 3, с. 20–21, удержание и отпускание',[PRACTICE]:'Duke и Simmons: небольшая цель практики'};
      l.sourceEvidenceIds=['ou-melodic-intervals-2026-11-05','kovarsky-fingering-context-2026-11-05','dumlavwalla-basic-technique-2026-11-05','czerny-letter3-release-2026-11-05','duke-simmons-small-goals-2026-11-05'];
      l.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:r.purpose,context:'Две ноты одной рукой уплотняют мелодию и применяются в сопровождении. Здесь сначала согласуются два подготовленных пальца; переходы между разными формами и независимые голоса требуют следующих шагов.',sourceNote:'Это существующая отработка проекта, не фрагмент произведения и не упражнение, приписанное Черни. OpenLearn, §6.4, объясняет гармонический интервал как два одновременных звука; конкретные интервалы сверены по MIDI: C–E четыре полутона, D–F три. Kovarsky подтверждает номера 1–5 и планирование позиции, не единственную аппликатуру этих пар. Наши '+r.digits+' выбраны для знакомой пятипальцевой позиции. Dumlavwalla описывает поддержанную руку и гибкое запястье. Черни в письме 3, с. 20–21, различает удержание клавиши и паузу; наш рисунок, 0,85 доли, 56 BPM и допуск общего отпускания ему не принадлежат. Авторы не утверждали эти уроки или весь курс.'};
      l.contentReview={id:'dyad-preparation-release-v1',sourceFingerprint:r.fingerprint,previousAssessmentFingerprint,previousInstruction,reviewedFingerprint:instructionFingerprint(lesson)};changed++;
    }
    return changed;
  }
  function reviewEarlyRelease(lessons,adapter){
    let changed=0;
    for(const review of releaseReviews){
      const lesson=lessons.find(l=>l.id==='detail-p-release-'+review.suffix);
      if(!lesson?.learning||lesson.contentKind!=='exercise'||lesson.learning.contentReview||instructionFingerprint(lesson)!==review.fingerprint)continue;
      const learning=lesson.learning;
      const count='Считай «раз, два, три, четыре» ровно; новое нажатие приходится на каждую долю. При шести нотах продолжи «раз, два». Между атаками остаётся короткий просвет, как в образце; последнее нажатие тоже заканчивается отпусканием.';
      lesson.guide=adapter.normalizeGuide({...lesson.guide,setup:'Стопы устойчиво опираются на пол или подставку, плечи свободны, высота сиденья позволяет держать предплечья примерно на уровне клавиш. Педаль выключена. '+review.position,motion:review.movement,blind:'Сначала послушай образец и заранее представь начала и окончания звуков. После разбора повтори исходную фразу без подсказок; при потере позиции остановись и спокойно найди её снова.',mastery:'Три чистые MIDI-попытки исходной фразы, одна из памяти; ещё одна после перерыва, например завтра. '+review.hearing+' Пальцы и свободу движения проверь сам или с педагогом: MIDI их не определяет.'});
      learning.practiceSteps=[
        'Подготовка: '+review.position+' Послушай образец, затем назови и представь звуки. '+review.hearing,
        'Медленный разбор: сначала одно нажатие и отпускание без спешки, затем короткая последовательность. '+review.movement+' '+count,
        'Короткий блок практики — около 3–5 минут с остановками для проверки, без многократного силового повторения. После завершения попытки отдельно проверь перенос: '+review.transfer+' Это самостоятельная проба за инструментом, а не фраза текущего зачёта. Затем вернись к исходному уроку после перерыва.'
      ];
      learning.selfCheck=[...review.errors,review.hearing,'В MIDI-челлендже оцениваются ноты, пульс и окончания исходной фразы. Известный образец помогает слушать; это не независимый тест слуха.',review.nextText];
      learning.rhythmNotice='Non-legato означает раздельно, с небольшим просветом. Здесь вступления идут по одной доле при 56 BPM, а звук занимает около двух третей доли. Это настройка образца проекта, а не универсальное правило длительности ноты.';
      learning.coverageDomain='fingers';learning.nextLessonId=review.next;
      learning.references=[TECHNIQUE,CZERNY,PRACTICE];
      learning.referenceTitles={[TECHNIQUE]:'Diana Dumlavwalla: посадка, рука и запястье',[CZERNY]:'Карл Черни: письмо 3, с. 20–21',[PRACTICE]:'Bob Duke и Amy Simmons: короткая практика'};
      learning.provenance={type:'project-technical-drill',author:'Упражнение проекта',purpose:review.purpose,context:'Точное окончание ноты нужно в мелодии, повторяющихся звуках и басовом сопровождении: тишина и следующая атака тоже входят в музыкальную фразу.',sourceNote:'Ноты, пальцы и ритм придуманы для этой учебной задачи. Dumlavwalla объясняет удобную посадку и гибкое запястье; Черни обсуждает окончания нот. Источники не предписывают эту последовательность, 56 BPM или числовые допуски проекта.'};
      if(review.history)learning.provenance.history=review.history;
      learning.sourceEvidenceIds=['dumlavwalla-basic-technique-2026-11-05','czerny-letter3-release-2026-11-05','duke-simmons-small-goals-2026-11-05'];
      learning.contentReview={id:'early-release-v1',sourceFingerprint:review.fingerprint,reviewedFingerprint:instructionFingerprint(lesson)};changed++;
    }
    return changed;
  }
