  function upgradeReleaseLabels(lessons){
    const rules=[
      {id:'detail-p-release-03',fingerprint:'e470472c',replacements:[['из course01-03','из урока «Правая: C–D пальцами 1–2»']]},
      {id:'detail-p-release-04',fingerprint:'7614534f',replacements:[['в course01-04','в уроке «Левая: C–D пальцами 5–4»'],['в detail-p-legato-01','в уроке «Правая: соединить C4 и D4»']]}
    ];
    let changed=0;
    for(const rule of rules){
      const lesson=lessons.find(l=>l.id===rule.id),previous=lesson?.learning?.contentReview;
      if(lesson?.contentKind!=='exercise'||previous?.id!=='early-release-v1'||previous.reviewedFingerprint!==rule.fingerprint||instructionFingerprint(lesson)!==rule.fingerprint)continue;
      const replace=value=>rule.replacements.reduce((s,[from,to])=>s.replaceAll(from,to),value);
      lesson.guide.setup=replace(lesson.guide.setup);
      lesson.learning.practiceSteps=lesson.learning.practiceSteps.map(replace);
      lesson.learning.selfCheck=lesson.learning.selfCheck.map(replace);
      lesson.learning.contentReview={id:'early-release-v2',sourceFingerprint:rule.fingerprint,reviewedFingerprint:instructionFingerprint(lesson),previous:JSON.parse(JSON.stringify(previous))};changed++;
    }
    return changed;
  }
