      l.selfCheck=[...review.errors,review.hearing,'MIDI не определяет пальцы, расслабление, звуковой баланс и музыкальную выразительность. Известная фраза не является независимой слуховой пробой.',review.nextText];
      l.rhythmNotice='Новая учебная редакция ритма: '+(review.duration===1?'три такта 4/4, двенадцать четвертей':'четыре такта 4/4, восемь половинных событий')+'; '+bpm+' BPM. Высоты, руки и пальцы сохранены; длительности и тактовые границы уточнены. Прежние попытки сохраняются в своей версии, для нового зачёта нужен повтор. Бас и правая фраза здесь чередуются, это не упражнение на независимый удержанный голос. Числовые допуски — настройки проекта.';
      l.coverageDomain='coordination';l.nextLessonId=review.next;l.timingPrecision=review.precision;
      l.references=[METER,TIME_VALUES,PRACTICE,TECHNIQUE,HANDS_PRACTICE];l.referenceTitles={[METER]:'Robert Hutchinson: размер и число долей в такте',[TIME_VALUES]:'The Open University: четверти и половинные',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель',[TECHNIQUE]:'Diana Dumlavwalla: свободная рука',[HANDS_PRACTICE]:'Jerry Kovarsky: короткая подготовка трудного места'};
