      const l=lesson.learning,previousRhythm=JSON.parse(JSON.stringify(lesson.rhythm)),previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson),oct=r.right?'4':'3',digits=r.right?'1–3–5':'5–3–1',hand=r.right?'Правая':'Левая';
      lesson.rhythm=adapter.normalizeRhythm({...lesson.rhythm,source:'project-minor-comparison-v2',timeSignature:{numerator:3,denominator:4},steps:lesson.rhythm.steps.map((s,i)=>({...s,measure:i+1,beatInMeasure:0}))},4);
