    if(!lesson?.learning||(lesson.contentKind!==undefined&&lesson.contentKind!=='exercise')||lesson.learning.contentReview||instructionFingerprint(lesson)!==sourceFingerprint)return 0;
    const l=lesson.learning,previousRhythm=JSON.parse(JSON.stringify(lesson.rhythm)),previousInstruction=JSON.parse(JSON.stringify({description:lesson.description,guide:lesson.guide,learning:l})),previousAssessmentFingerprint=Assessment.pianoSignature(lesson);
    const phrase=[...Array(12).fill(1),1.5,.5,2];lesson.rhythm=rhythmFromDurations([...phrase,...phrase],66,'project-ode-memory-mutopia-528-v2',adapter);
    lesson.description='Закрепи две подготовленные фразы подряд. В каждом окончании сохраняй полторы доли — полдоли — две доли. Для проверки из памяти выбери «Из памяти по MIDI»: нот, пальцев и разбора в этом режиме нет.';
    lesson.guide=adapter.normalizeGuide({...lesson.guide,stage:'Закрепление двух фраз без подсказок',setup:'Сначала повтори course09-01 и course09-02. Правая в C4–G4 под пальцами 1–2–3–4–5; левая отдыхает, педаль выключена. Это повторение подготовленных задач, не новый навык из-за длины или режима памяти.',motion:'Окончание первой фразы E4–D4–D4 играй 3–2–2, второй D4–C4–C4 — 2–1–1. Половинная в конце первой звучит до следующего «раз», на котором начинается вторая фраза. Дополнительной паузы между ними нет; повторные клавиши получают новые нажатия.',blind:'«Без взгляда на руки» с видимым пальцем — вспомогательная практика. Для зачёта памяти выбери отдельный режим «Из памяти по MIDI», в котором скрыты все учебные подсказки. После первой ноты не слушай образец и не открывай редактор; использованная подсказка снимает зачёт этой попытки.',mastery:'Проверь оба пунктирных окончания, переход к пятому такту и полное последнее удержание. MIDI не доказывает пальцы, свободу руки или художественное качество. Немедленная память и отсроченный повтор учитываются отдельно; после перерыва вернись к задаче.'});
    l.stage='p3';l.after='course09-02';l.requires=['course09-01','course09-02'];l.sameGoalAs='course09-02';l.coverageDomain='ear-transfer';l.articulation='standard';l.timingPrecision='beat-boundary-v1';l.goal=lesson.description;l.nextLessonId='course09-03';
    l.practiceSteps=[
      'Подготовка: отдельно сыграй обе проверенные фразы и заранее услышь их разные окончания — сначала D4, затем C4. Первые три такта каждой фразы состоят из четвертей; в четвёртом полторы доли, полдоли и две доли. Сохраняй правые пальцы 1–5 и новые нажатия повторных E4, G4, C4 и конечных пар. Можно послушать образец до первой ноты; затем начни самостоятельную попытку.',
      'Медленный разбор: считай «раз-и, два-и, три-и, четыре-и». В тактах 4 и 8 первый звук вступает на «раз», короткий — на «два-и», половинная — на «три» и длится до следующего «раз». В конце такта 4 отпусти D4 и на том же новом «раз» сыграй E4, начиная вторую фразу. Первая фраза занимает доли 0–16, вторая 16–32; внутренних пауз нет. Ноты и пальцы сохранены, учебный темп здесь 66 BPM, не темп 100 в источнике.',
      'Блок около 3–5 минут: сначала трудное окончание и стык фраз в практике, затем вся связка. Выбери «Из памяти по MIDI» для попытки с действительно скрытыми нотами и пальцами; один режим без взгляда на руки этого не заменяет. После первой ноты прослушивание или просмотр подсказки не даст зачёта памяти. После перерыва повтори; отдельно начни сразу со второй фразы и проверь её окончание на C4. Изменённая точка начала — самостоятельная проба переноса, не новый урок и не независимый слуховой тест. Полное разучивание произведения остаётся в отдельном разделе.'
    ];
    l.selfCheck=['В тактах 4 и 8 не выравнивай 1,5 и 0,5 доли до двух четвертей.','Две доли последней D4 первой фразы заменяют прежнюю короткую ноту с лишней паузой: вторая фраза начинается на доле 16.','Последний C4 держи две полные доли до границы 32. Попытка завершается только после отпускания; последующая тишина не оценивается.','В режиме памяти текущий палец тоже скрыт. Прослушанная после начала попытка не получает зачёт памяти; прежние результаты других попыток сохраняются.','Повторение длиной восемь тактов не объявлено новым самостоятельным навыком. MIDI не проверяет номера пальцев, комфорт, звуковой баланс и выразительность.'];
    l.rhythmNotice='Редакция по Mutopia, soprano, страница 1, такты 1–8: восемь тактов 4/4, два пунктирных окончания, всего 32 доли. Раньше звучало 30 четвертей с однодольной паузой на стыке: общий отрезок 31 доля. Теперь окончания 1,5–0,5–2, пауза на стыке убрана, начало второй фразы на доле 16 сохранено. 66 BPM, пальцы и допуски выбраны проектом. Старые ритм, инструкции и результаты сохранены в истории; новый зачёт относится к новой версии.';
    l.references=[ODE_SCORE,ODE_CATALOG,DOTS,PRACTICE];l.referenceTitles={[ODE_SCORE]:'Бетховен / Mutopia: soprano, такты 1–8',[ODE_CATALOG]:'Mutopia 528: издание и Public Domain',[DOTS]:'The Open University: четверть с точкой',[PRACTICE]:'Bob Duke и Amy Simmons: небольшая цель, другая точка начала, повтор после перерыва'};l.sourceEvidenceIds=['mutopia-528-ode-2026-11-05','ou-dots-and-ties-2026-11-05','duke-simmons-small-goals-2026-11-05'];
    l.provenance={type:'study-or-adaptation',author:'Людвиг ван Бетховен — мелодия; Peter Chubb / Mutopia — нотный набор; проект — учебная адаптация.',purpose:'Закрепить уже подготовленные разные окончания двух фраз и повторить их подряд без учебных подсказок. Это повторение цели course09-02, не новая самостоятельная задача из-за длины или памяти.',context:'Сборка знакомой мелодии и повтор после перерыва. Полный разбор произведения изучается отдельно; конкретная пьеса не становится обязательной подготовкой общего навыка памяти.',sourceNote:'Ode to Joy, Mutopia-2009/08/05-528, страница 1, soprano, такты 1–8. Использована проверенная мелодия из нотного набора Peter Chubb, помеченного Public Domain. G major → C major вниз на 7 полутонов; остальные три голоса исключены. Правая рука, пальцы 1–5 и 66 BPM вместо 100 — решения проекта. Каталог указывает Source: Various; эта гимновая редакция не выдана за автограф или критическое издание симфонии.',score:{edition:'Mutopia-2009/08/05-528',url:ODE_SCORE,part:'soprano',page:1,bars:[1,8],sourceKey:'G major',targetKey:'C major',transpositionSemitones:-7,sourceQuarterBpm:100,projectQuarterBpm:66,rights:'Public Domain declared by typesetter'}};
